def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {"inland": 4.20, "coastal": 5.75, "highland": 9.10}
    if zone not in rates:
        raise ValueError("invalid zone")
    if weight_kg <= 0:
        raise ValueError("weight_kg must be greater than zero")

    base_rate = rates[zone]
    subtotal = (
        min(weight_kg, 10) * base_rate
        + min(max(weight_kg - 10, 0), 40) * 0.60 * base_rate
        + max(weight_kg - 50, 0) * 0.35 * base_rate
    )
    subtotal = round(subtotal, 2)

    if subtotal.is_integer():
        subtotal -= 2.00

    if is_perishable and zone != "highland":
        subtotal += 18.50

    return float(round(subtotal, 2))

def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    from decimal import Decimal, ROUND_HALF_EVEN

    rates = {
        "inland": Decimal("4.20"),
        "coastal": Decimal("5.75"),
        "highland": Decimal("9.10"),
    }

    if zone not in rates:
        raise ValueError("invalid zone")
    if weight_kg <= 0:
        raise ValueError("weight_kg must be greater than zero")

    weight = Decimal(str(weight_kg))
    base_rate = rates[zone]

    subtotal = (
        min(weight, Decimal("10")) * base_rate
        + min(max(weight - Decimal("10"), Decimal("0")), Decimal("40"))
        * Decimal("0.60")
        * base_rate
        + max(weight - Decimal("50"), Decimal("0"))
        * Decimal("0.35")
        * base_rate
    )
    subtotal = subtotal.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)

    if subtotal == subtotal.to_integral_value():
        subtotal -= Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += Decimal("18.50")

    return float(subtotal.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN))

